import "./globals.css";
import type { Metadata } from "next";
import { ReactNode } from "react";
import { IBM_Plex_Sans } from "next/font/google";
import { AppRouterCacheProvider } from "@mui/material-nextjs/v15-appRouter";
import { EasyPrintThemeProvider } from "../theme/easyprint-theme-provider";

const ibmPlexSans = IBM_Plex_Sans({
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
  variable: "--font-easyprint",
  display: "swap"
});

export const metadata: Metadata = {
  title: "EasyPrint",
  description: "Plataforma de criacao, edicao e impressao de etiquetas"
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="pt-BR" className={ibmPlexSans.variable}>
      <body>
        <AppRouterCacheProvider options={{ enableCssLayer: true }}>
          <EasyPrintThemeProvider>{children}</EasyPrintThemeProvider>
        </AppRouterCacheProvider>
      </body>
    </html>
  );
}
